# Generated by Descant: acceptance tests.
# frozen_string_literal: true

require "rails_helper"

RSpec.describe "Timekeeping handoff load transaction" do
  include_context "timekeeping entry writes without transactional fixtures"

  let(:load_tx_service_token) { "service-#{SecureRandom.hex(24)}" }

  around do |example|
    with_timekeeping_env(Timekeeping::Environment::SERVICE_TOKEN => load_tx_service_token) { example.run }
  end

  # "Timekeeping's load replaces its tables in one transaction"
  it "rolls back the whole load when a reservation fails to insert after the entries were replaced" do
    now = Time.utc(2026, 3, 2, 9)
    Entry.create!(id: 41, company_id: 1, version: 2, project_id: 5, user_id: 7, work_date: Date.new(2026, 3, 2),
                  duration: 60.0, note: "kept", bill_status: "unbilled", created_at: now, updated_at: now)
    Reservation.create!(company_id: 1, entry_id: 41, invoice_id: 9, state: "committed", disposition: "active",
                        operation_id: SecureRandom.uuid, created_at: now)
    Timekeeping::Admission.fence!
    auth = { "Authorization" => "Bearer #{load_tx_service_token}" }

    get "/internal/v1/handoff/checkpoint", headers: auth
    expect(response.status).to eq(200)
    rows = Timekeeping::Handoff::Checkpoint.from_json(response.body).rows.transform_values { |list| list.map(&:dup) }
    rows["entries"] = rows["entries"].map { |row| row.merge("note" => "replaced") }
    # A reservation for an entry the checkpoint does not hold breaks the
    # composite foreign key only after the entries have been rewritten.
    rows["reservations"] = rows["reservations"].map { |row| row.merge("entry_id" => 999) }
    broken = Timekeeping::Handoff::Checkpoint.build(tables: rows)

    put "/internal/v1/handoff/checkpoint", params: broken.to_json,
                                           headers: auth.merge("Content-Type" => "application/json")

    expect(response.status).not_to eq(200)
    expect(Entry.pluck(:id, :note, :version)).to eq([[41, "kept", 2]])
    expect(Reservation.pluck(:entry_id, :invoice_id)).to eq([[41, 9]])
  end
end

RSpec.describe "Timekeeping handoff load digest" do
  include_context "timekeeping entry writes without transactional fixtures"

  let(:digest_service_token) { "service-#{SecureRandom.hex(24)}" }

  around do |example|
    with_timekeeping_env(Timekeeping::Environment::SERVICE_TOKEN => digest_service_token) { example.run }
  end

  # "Recompute the digest inside the transaction and roll back on a mismatch."
  it "refuses a checkpoint body edited after its digest was written and keeps the stored entry" do
    now = Time.utc(2026, 3, 2, 9)
    Entry.create!(id: 52, company_id: 3, version: 1, project_id: 5, user_id: 7, work_date: Date.new(2026, 3, 2),
                  duration: 30.0, note: "original", bill_status: "unbilled", created_at: now, updated_at: now)
    Timekeeping::Admission.fence!
    auth = { "Authorization" => "Bearer #{digest_service_token}" }

    get "/internal/v1/handoff/checkpoint", headers: auth
    document = JSON.parse(response.body)
    document["tables"]["entries"].each do |pairs|
      pairs.each { |pair| pair[1] = ["str", "tampered"] if pair[0] == "note" }
    end

    put "/internal/v1/handoff/checkpoint", params: JSON.generate(document),
                                           headers: auth.merge("Content-Type" => "application/json")

    expect([response.status, response.parsed_body]).to eq([409, { "reason" => "handoff_refused" }])
    expect(Entry.pluck(:id, :note)).to eq([[52, "original"]])
  end
end
